/* Reset */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

@font-face {
    font-family: 'OPTISwallow';
    src: url('fonts/OPTISwallow.woff2') format('woff2'),
         url('fonts/OPTISwallow.woff') format('woff'),
         url('fonts/OPTISwallow.ttf') format('truetype');
    font-weight: 400;
    font-style: normal;
    font-display: swap;
}

body {
    font-family: 'Inter', sans-serif;
    background-color: #000;
    color: #fff;
    height: 100vh;
    overflow: hidden;
    position: relative;
}

/* Animacje globalne */
@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes slideInLeft {
    from { opacity: 0; transform: translateX(-30px); }
    to { opacity: 1; transform: translateX(0); }
}

@keyframes slideInRight {
    from { opacity: 0; transform: translateX(30px); }
    to { opacity: 1; transform: translateX(0); }
}

@keyframes pulse {
    0%, 100% { opacity: 0.8; }
    50% { opacity: 1; }
}

/* Tło - okładka */
.background {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 0;
    pointer-events: none;
    background-image: url("data:image/jpeg;base64,");
    background-size: cover;
    background-position: center;
}

.gradient-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(to right, rgba(0, 0, 0, 0.95) 0%, rgba(0, 0, 0, 0.7) 30%, transparent 50%);
    pointer-events: none;
}

/* SSM Label - lewy górny róg */
.ssm-label {
    position: fixed;
    top: 40px;
    left: 40px;
    color: #fff;
    text-decoration: none;
    font-size: clamp(10px, 1.5vw, 14px);
    font-weight: 600;
    letter-spacing: 1px;
    text-transform: uppercase;
    z-index: 100;
    transition: all 0.3s ease;
    opacity: 0;
    animation: slideInLeft 0.8s ease forwards 0.2s;
}

.ssm-label:hover {
    opacity: 0.7;
}

/* Copyright - prawy górny róg */
.copyright-top {
    position: fixed;
    top: 40px;
    right: 40px;
    font-size: clamp(7px, 1.2vw, 10px);
    font-weight: 400;
    line-height: 1.5;
    text-align: right;
    opacity: 0;
    max-width: clamp(140px, 40vw, 500px);
    z-index: 100;
    letter-spacing: 0.3px;
    animation: slideInRight 0.8s ease forwards 0.3s;
}

.copyright-top:hover {
    opacity: 0.8;
}

.copyright-full {
    display: block;
}

.copyright-mobile {
    display: none;
}

/* Lewa zawartość */
.left-content {
    position: fixed;
    left: 40px;
    top: 50%;
    transform: translateY(-50%);
    z-index: 10;
    max-width: 500px;
}

.release-info {
    opacity: 0;
    animation: slideInLeft 1s ease forwards 0.5s;
}

.release-info h1 {
    font-size: clamp(36px, 8vw, 72px);
    font-weight: 700;
    letter-spacing: -2px;
    margin-bottom: 10px;
    line-height: 1;
    transition: all 0.3s ease;
}

.release-info h1:hover {
    opacity: 0.9;
}

.release-date {
    font-size: clamp(11px, 2vw, 16px);
    font-weight: 500;
    letter-spacing: clamp(1.5px, 0.3vw, 3px);
    text-transform: uppercase;
    opacity: 0.8;
    margin-bottom: clamp(30px, 4vh, 40px);
    animation: pulse 3s ease-in-out infinite;
}

/* Single Section */
.single-section {
    margin-bottom: clamp(35px, 5vh, 50px);
    padding: clamp(20px, 3vw, 30px);
    border: 1px solid rgba(255, 255, 255, 0.2);
    background: rgba(0, 0, 0, 0.4);
    backdrop-filter: blur(10px);
    border-radius: clamp(4px, 0.8vw, 8px);
    opacity: 0;
    animation: fadeIn 1s ease forwards 0.7s;
}

.single-badge {
    font-size: clamp(9px, 1.2vw, 11px);
    font-weight: 600;
    letter-spacing: 1.5px;
    color: #fff;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.3);
    padding: clamp(4px, 0.6vw, 6px) clamp(10px, 1.5vw, 14px);
    display: inline-block;
    margin-bottom: 15px;
    text-transform: uppercase;
    border-radius: 2px;
}

.single-title {
    margin-bottom: 8px;
}

.single-title-bg {
    width: min(100%, 340px);
    aspect-ratio: 283.46 / 127.32;
    background-image: url("data:image/svg+xml;base64,");
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
}

.single-status {
    font-size: clamp(10px, 1.5vw, 13px);
    font-weight: 500;
    letter-spacing: clamp(1.3px, 0.25vw, 2px);
    text-transform: uppercase;
    opacity: 0.7;
    margin-bottom: clamp(15px, 2vh, 20px);
}

.single-listen-btn {
    display: inline-block;
    color: #fff;
    text-decoration: none;
    font-size: clamp(11px, 1.5vw, 13px);
    font-weight: 600;
    padding: clamp(11px, 1.5vh, 12px) clamp(20px, 3vw, 28px);
    border: 1px solid rgba(255, 255, 255, 0.3);
    text-transform: uppercase;
    letter-spacing: 1.5px;
    transition: all 0.3s ease;
    background: rgba(255, 255, 255, 0.05);
    border-radius: clamp(3px, 0.6vw, 8px);
}

.single-listen-btn:hover {
    background: #fff;
    color: #000;
    border-color: #fff;
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(255, 255, 255, 0.3);
}

.social-links {
    display: flex;
    gap: 20px;
    opacity: 0;
    animation: fadeIn 1s ease forwards 0.8s;
}

.social-btn {
    color: #fff;
    text-decoration: none;
    font-size: clamp(12px, 1.5vw, 14px);
    font-weight: 500;
    padding: clamp(10px, 1.5vh, 12px) clamp(18px, 2.5vw, 24px);
    border: 1px solid rgba(255, 255, 255, 0.3);
    transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    text-transform: uppercase;
    letter-spacing: 1px;
    position: relative;
    overflow: hidden;
}

.social-btn::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: #fff;
    transition: left 0.4s ease;
    z-index: -1;
}

.social-btn:hover::before {
    left: 0;
}

.social-btn:hover {
    color: #000;
    border-color: #fff;
}

.bottom-right {
    position: fixed;
    bottom: 40px;
    right: 40px;
    z-index: 100;
    opacity: 0;
    animation: slideInRight 0.8s ease forwards 0.7s;
}

.streaming-toggle {
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.3);
    color: #fff;
    font-size: clamp(11px, 1.5vw, 14px);
    font-weight: 500;
    padding: clamp(9px, 1.5vh, 12px) clamp(16px, 2.5vw, 24px);
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.3s ease;
    backdrop-filter: blur(10px);
    letter-spacing: 1px;
    text-transform: uppercase;
}

.streaming-toggle:hover {
    background: rgba(255, 255, 255, 0.2);
    border-color: #fff;
}

.streaming-toggle:active {
    opacity: 0.8;
}

.streaming-modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    z-index: 1000;
    justify-content: center;
    align-items: center;
    backdrop-filter: blur(12px);
}

.streaming-modal.active {
    display: flex;
    animation: fadeIn 0.3s ease;
}

.modal-content {
    background: rgba(0, 0, 0, 0.5);
    border: 1px solid rgba(255, 255, 255, 0.12);
    padding: clamp(30px, 5vw, 50px) clamp(25px, 6vw, 60px);
    position: relative;
    width: min(calc(100% - 30px), 500px);
    border-radius: clamp(16px, 2.5vw, 24px);
    backdrop-filter: blur(30px) saturate(150%);
    -webkit-backdrop-filter: blur(30px) saturate(150%);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3), inset 0 1px 0 0 rgba(255, 255, 255, 0.08);
    animation: modalSlideIn 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

@keyframes modalSlideIn {
    from { opacity: 0; transform: translateY(-20px) scale(0.95); }
    to { opacity: 1; transform: translateY(0) scale(1); }
}

.close-modal {
    position: absolute;
    top: 25px;
    right: 25px;
    background: none;
    border: none;
    color: #fff;
    font-size: 28px;
    cursor: pointer;
    opacity: 0.6;
    transition: opacity 0.3s ease;
    padding: 0;
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 10;
}

.close-modal:hover {
    opacity: 1;
}

.modal-content h3 {
    font-size: clamp(20px, 4vw, 32px);
    font-weight: 600;
    margin-bottom: clamp(25px, 4vh, 40px);
    letter-spacing: -0.5px;
    text-align: center;
    opacity: 0.95;
}

.streaming-link {
    display: block;
    color: #fff;
    text-decoration: none;
    padding: clamp(14px, 2vh, 18px) clamp(20px, 3vw, 30px);
    border: 1px solid rgba(255, 255, 255, 0.15);
    margin-bottom: clamp(12px, 1.5vh, 16px);
    font-size: clamp(12px, 1.8vw, 15px);
    font-weight: 500;
    transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    text-transform: uppercase;
    letter-spacing: 1.2px;
    border-radius: clamp(12px, 1.8vw, 16px);
    text-align: center;
    background: rgba(255, 255, 255, 0.03);
    backdrop-filter: blur(10px);
    position: relative;
    overflow: hidden;
}

.streaming-link:last-child {
    margin-bottom: 0;
}

.streaming-link:hover {
    border-color: rgba(255, 255, 255, 0.6);
    background: rgba(255, 255, 255, 0.95);
    color: #000;
    transform: translateY(-2px);
    box-shadow: 0 12px 30px rgba(255, 255, 255, 0.2);
}

.streaming-link.spotify:hover,
.streaming-link.apple:hover,
.streaming-link.youtube:hover {
    background: rgba(255, 255, 255, 0.95);
    border-color: rgba(255, 255, 255, 0.6);
    color: #000;
    box-shadow: 0 12px 30px rgba(255, 255, 255, 0.2);
}

@media (max-width: 768px) {
    .ssm-label {
        top: 20px;
        left: 20px;
        font-size: 11px;
    }

    .copyright-top {
        font-size: 8px;
        max-width: 180px;
        line-height: 1.5;
    }

    .copyright-full { display: none; }
    .copyright-mobile { display: block; font-size: 10px; }

    .left-content {
        left: 15px;
        right: 15px;
        max-width: calc(100% - 30px);
        text-align: center;
        top: auto;
        bottom: 15px;
        transform: none;
    }

    .release-info h1 {
        font-size: 52px;
        letter-spacing: -1px;
    }

    .release-date {
        font-size: 13px;
        letter-spacing: 2px;
        margin-bottom: 30px;
    }

    .single-section {
        padding: 30px 25px;
        margin-bottom: 35px;
        border-radius: 8px;
    }

    .single-badge {
        font-size: 11px;
        padding: 6px 14px;
    }

    .single-title { font-size: 36px; }

    .single-status {
        font-size: 12px;
        letter-spacing: 1.8px;
        margin-bottom: 20px;
    }

    .single-listen-btn {
        font-size: 13px;
        padding: 14px 28px;
        width: 100%;
        text-align: center;
        border-radius: 8px;
    }

    .social-links {
        flex-direction: column;
        gap: 12px;
        width: 100%;
    }

    .social-btn {
        text-align: center;
        width: 100%;
        padding: 16px 22px;
        font-size: 14px;
    }

    .bottom-right {
        bottom: 20px;
        left: 50%;
        right: auto;
        transform: translateX(-50%);
        width: fit-content;
        display: none;
    }

    .streaming-toggle {
        font-size: 12px;
        padding: 10px 20px;
    }

    .modal-content h3 {
        font-size: 24px;
        margin-bottom: 30px;
    }

    .streaming-link {
        padding: 16px 24px;
        font-size: 14px;
        margin-bottom: 14px;
        border-radius: 14px;
    }

    .gradient-overlay {
        background: linear-gradient(to top, rgba(0, 0, 0, 0.6) 0%, rgba(0, 0, 0, 0.45) 40%, rgba(0, 0, 0, 0) 100%);
    }
}

@media (max-width: 480px) {
    .ssm-label { font-size: 10px; top: 15px; left: 15px; }
    .copyright-top { font-size: 7px; max-width: 140px; top: 15px; right: 15px; }
    .copyright-full { display: none; }
    .copyright-mobile { display: block; font-size: 11px; }
    .left-content { left: 15px; right: 15px; max-width: calc(100% - 30px); text-align: center; top: auto; bottom: 15px; transform: none; }
    .release-info h1 { font-size: 40px; }
    .release-date { font-size: 11px; letter-spacing: 1.5px; margin-bottom: 25px; }
    .single-section { padding: 25px 20px; margin-bottom: 30px; border-radius: 8px; }
    .single-badge { font-size: 10px; padding: 5px 12px; }
    .single-title { font-size: 32px; }
    .single-status { font-size: 11px; letter-spacing: 1.5px; margin-bottom: 18px; }
    .single-listen-btn { font-size: 12px; padding: 13px 24px; width: 100%; text-align: center; border-radius: 8px; }
    .social-btn { font-size: 13px; padding: 14px 18px; }
    .bottom-right { bottom: 15px; left: 50%; right: auto; transform: translateX(-50%); width: fit-content; display: none; }
    .streaming-toggle { font-size: 11px; padding: 9px 16px; }
    .modal-content h3 { font-size: 22px; margin-bottom: 25px; }
    .streaming-link { padding: 15px 20px; font-size: 13px; border-radius: 12px; }
    .gradient-overlay { background: linear-gradient(to top, rgba(0, 0, 0, 0.6) 0%, rgba(0, 0, 0, 0.45) 50%, rgba(0, 0, 0, 0) 100%); }
}

@media (max-width: 768px) and (orientation: landscape) {
    .left-content { top: 50%; }
    .release-info h1 { font-size: 40px; }
    .release-date { margin-bottom: 25px; }
    .social-links { flex-direction: row; flex-wrap: wrap; }
    .social-btn { flex: 1; min-width: 120px; }
}
